import { Component, Input, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-software-package-card',
  templateUrl: './software-package-card.component.html',
  styleUrls: ['./software-package-card.component.css']
})
export class SoftwarePackageCardComponent {
  @Input() package!: SoftwarePackage;
  @Output() click = new EventEmitter<SoftwarePackage>();

  constructor(private router: Router) {}

  onClick(): void {
    this.click.emit(this.package);
  }

  orderPackage(event: Event): void {
    event.stopPropagation();
    this.router.navigate(['/packages', this.package.id, 'order']);
  }
}
<div class="card p-4 cursor-pointer" (click)="onClick()">
  <div class="aspect-square mb-3 overflow-hidden rounded-lg bg-gray-100">
    <img
      [src]="package.thumbnail || package.images?.[0] || 'https://via.placeholder.com/300'"
      [alt]="package.title"
      class="w-full h-full object-cover hover:scale-105 transition-transform duration-300"
    />
  </div>

  <h3 class="font-semibold text-gray-900 mb-2 line-clamp-2">{{ package.title }}</h3>

  <button
    (click)="orderPackage($event)"
    class="w-full bg-orange-500 text-white py-4 rounded-xl font-bold text-xl hover:bg-orange-600 transition-colors shadow-lg mb-4 border-2 border-orange-700"
  >
    <span class="flex items-center justify-center gap-2">
      <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
      </svg>
      ORDER NOW
    </span>
  </button>

  <div class="flex items-center text-sm text-gray-600">
    <svg class="w-4 h-4 text-yellow-400 mr-1" fill="currentColor" viewBox="0 0 20 20">
      <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
    </svg>
    <span>{{ package.rating || 'N/A' }}</span>
  </div>

  <p class="text-sm text-gray-500 line-clamp-2 mt-2">{{ package.description }}</p>
</div>
